#!/usr/bin/env node
// Generates responsive WebP variants and a tiny blur placeholder for every
// photo the page uses. Run after adding or replacing a source image:
//   pnpm images:build
// The generated files and lib/photos.ts are committed, so builds and CI never
// need sharp.
import { mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import sharp from 'sharp';

const WIDTHS = [320, 640, 1080];
const OUT_DIR = 'public/img';

const SOURCES = [
  ['clothing', 'public/clothing.jpg'],
  ['nail-tech', 'public/nail-tech.jpg'],
  ['photography', 'public/photography.jpg'],
  ['mentorship', 'public/mentorship.jpg'],
  ['hair', 'public/hustles/hair.jpg'],
  ['beauty', 'public/hustles/beauty.jpg'],
  ['thrift', 'public/hustles/thrift.jpg'],
  ['food', 'public/hustles/food.jpg'],
  ['events', 'public/hustles/photography.jpg'],
];

await mkdir(OUT_DIR, { recursive: true });

const entries = [];

for (const [name, source] of SOURCES) {
  const image = sharp(source);
  const meta = await image.metadata();
  const sourceWidth = Math.min(meta.width ?? 1080, 1080);
  const ratio = (meta.height ?? 1080) / (meta.width ?? 1080);

  const widths = [...new Set(WIDTHS.map((width) => Math.min(width, sourceWidth)))];
  for (const width of widths) {
    await sharp(source)
      .resize({ width, withoutEnlargement: true })
      .webp({ quality: 72, effort: 5 })
      .toFile(path.join(OUT_DIR, `${name}-${width}.webp`));
  }

  // 24px wide blur, inlined as a data URL so there is no extra request.
  const blurBuffer = await sharp(source).resize({ width: 24 }).webp({ quality: 35 }).toBuffer();
  const blur = `data:image/webp;base64,${blurBuffer.toString('base64')}`;

  // Average colour as a background while the image loads.
  const { dominant } = await sharp(source).stats();
  const color = `#${[dominant.r, dominant.g, dominant.b]
    .map((channel) => channel.toString(16).padStart(2, '0'))
    .join('')}`;

  entries.push({
    name,
    width: sourceWidth,
    height: Math.round(sourceWidth * ratio),
    widths,
    color,
    blur,
  });

  console.log(`ok ${name.padEnd(14)} ${sourceWidth}px  blur ${(blur.length / 1024).toFixed(1)} kB`);
}

const file = `// Generated by scripts/optimize-images.mjs. Do not edit by hand.
// Run \`pnpm images:build\` after changing a source photo.

export type PhotoMeta = {
  width: number;
  height: number;
  widths: number[];
  color: string;
  blur: string;
};

export const photos = ${JSON.stringify(
  Object.fromEntries(entries.map(({ name, ...rest }) => [name, rest])),
  null,
  2,
)} as const;

export type PhotoName = keyof typeof photos;
`;

await writeFile('lib/photos.ts', file);
console.log(`wrote lib/photos.ts (${entries.length} photos)`);
